package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmployeeReferral; import EmployeeManagementSystem.repository.EmployeeReferralRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EmployeeReferralServiceImpl implements EmployeeReferralService{
 private final EmployeeReferralRepository repo; public EmployeeReferralServiceImpl(EmployeeReferralRepository r){repo=r;}
 public List<EmployeeReferral> my(String u){return repo.findByReferrerUserIdOrderByCreatedAtDesc(u);} public List<EmployeeReferral> all(){return repo.findAllByOrderByCreatedAtDesc();}
 public EmployeeReferral create(EmployeeReferral x,String u,String n){if(x.getCandidateName()==null||x.getCandidateName().isBlank()||x.getCandidateEmail()==null||x.getCandidateEmail().isBlank()||x.getPosition()==null||x.getPosition().isBlank())throw new IllegalArgumentException("Candidate name, email and position are required."); if(repo.existsByReferrerUserIdAndCandidateEmailAndStatusIn(u,x.getCandidateEmail(),List.of("SUBMITTED","UNDER_REVIEW","SHORTLISTED")))throw new IllegalArgumentException("An active referral already exists for this candidate email."); x.setId(null);x.setReferralNumber("REF-"+System.currentTimeMillis());x.setReferrerUserId(u);x.setReferrerName(n);x.setStatus("SUBMITTED");return repo.save(x);}
 public EmployeeReferral review(Long id,String s,String c,String r){EmployeeReferral x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Referral not found."));if(!Set.of("UNDER_REVIEW","SHORTLISTED","INTERVIEW","HIRED","REJECTED","WITHDRAWN").contains(s))throw new IllegalArgumentException("Invalid referral status.");x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setReviewedAt(java.time.LocalDateTime.now());return repo.save(x);}
}
